(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s);
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[m]))}
function age(v){const t=Date.parse(v||'');if(!Number.isFinite(t))return '';const m=Math.max(1,Math.floor((Date.now()-t)/60000));if(m<60)return `منذ ${m} د`;const h=Math.floor(m/60);if(h<24)return `منذ ${h} س`;return `منذ ${Math.floor(h/24)} ي`}
function isDashboard(){return $('[data-view="dashboard"]')?.classList.contains('active')!==false&&!!$('.v8-main')}
function stateStats(s){const tasks=s.tasks||[],employees=s.employees||[],projects=s.projects||[];const active=tasks.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status));const waiting=tasks.filter(t=>t.status==='WAITING_FOR_NAWAF');const done=tasks.filter(t=>t.status==='COMPLETED');const blocked=tasks.filter(t=>t.blockedReason&&t.status!=='COMPLETED');const busyEmployees=employees.filter(e=>['WORKING','RESEARCHING','REVIEWING'].includes(e.status));const completion=tasks.length?Math.round(done.length/tasks.length*100):0;return {tasks,employees,projects,active,waiting,done,blocked,busyEmployees,completion}}
function projectHealth(p,s){const ts=(s.tasks||[]).filter(t=>t.projectId===p.id),bad=ts.filter(t=>t.blockedReason||t.status==='WAITING_FOR_NAWAF').length,active=ts.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status)).length,done=ts.filter(t=>t.status==='COMPLETED').length;let score=100;if(bad)score-=Math.min(55,bad*18);if(ts.length&&!done&&!active)score-=12;if(p.status==='PAUSED')score=55;return {score:Math.max(0,score),bad,active,done,total:ts.length}}
function priority(s){const weight=t=>(t.status==='WAITING_FOR_NAWAF'?100:0)+(t.blockedReason?70:0)+(t.priority==='URGENT'?60:t.priority==='HIGH'?30:0)+(['WORKING','RESEARCHING','REVIEWING'].includes(t.status)?20:0);return [...(s.tasks||[])].filter(t=>t.status!=='COMPLETED').sort((a,b)=>weight(b)-weight(a)).slice(0,5)}
function employeeLoad(e,s){const all=(s.tasks||[]).filter(t=>t.employeeId===e.id&&t.status!=='COMPLETED');const working=all.filter(t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status));const current=working[0]||all[0]||null;return {count:all.length,load:Math.min(100,all.length*24+working.length*22),current}}
function statusLabel(v){return ({READY:'متاح',WORKING:'يعمل الآن',RESEARCHING:'يبحث',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظارك',PAUSED:'متوقف'})[v]||v||'متاح'}
function quickAction(label,action,kind=''){return `<button type="button" class="v14-quick ${kind}" data-v14-action="${action}"><span>${esc(label)}</span><small>فتح مباشر</small></button>`}
function tool(name,status,url,sub=''){const tag=url?'a':'div';const attrs=url?` href="${url}" target="_blank" rel="noopener noreferrer"`:'';return `<${tag} class="v14-tool"${attrs}><span><b>${esc(name)}</b><small>${esc(sub)}</small></span><i>${esc(status)}</i></${tag}>`}
function render(){const main=$('.v8-main');if(!main)return;if(!isDashboard()){main.classList.remove('v14-home');return}main.classList.add('v14-home');let root=$('.v14-dashboard');if(!root){root=document.createElement('section');root.className='v14-dashboard';const header=main.querySelector('.v8-header');if(header)header.insertAdjacentElement('afterend',root);else main.prepend(root)}const s=read(),x=stateStats(s),prio=priority(s),activity=(s.activity||[]).slice(0,4),systemCloud=window.HQCloud?.status?.()||{};
root.innerHTML=`
<div class="v14-hero"><div><span class="v14-eyebrow">NAWAF HQ</span><h2>وش يحتاج انتباهك الآن؟</h2><p>المهم فقط: التنفيذ، القرارات، المشاريع، والأدوات المربوطة.</p></div><div class="v14-score"><strong>${x.completion}%</strong><span>إنجاز المهام</span></div></div>
<div class="v14-kpis">
 <button data-v14-go="tasks"><b>${x.active.length}</b><span>يعمل الآن</span><small>${x.busyEmployees.length} موظف نشط</small></button>
 <button data-v14-action="decisions"><b>${x.waiting.length}</b><span>يحتاج قرارك</span><small>${x.waiting.length?'راجعها الآن':'ما فيه شيء معلق'}</small></button>
 <button data-v14-go="projects"><b>${x.projects.filter(p=>p.status==='ACTIVE').length}</b><span>مشاريع نشطة</span><small>${x.projects.length} مشاريع إجمالًا</small></button>
 <button data-v14-action="sync"><b>${systemCloud.cloud===false?'!':'✓'}</b><span>المزامنة</span><small>${systemCloud.dirty?'تغييرات بانتظار الحفظ':'الحالة السحابية مستقرة'}</small></button>
</div>
<div class="v14-grid">
 <article class="v14-card"><header><div><span>FOCUS</span><h3>أولوياتك الآن</h3></div><button data-v14-go="tasks">كل المهام</button></header><div>${prio.length?prio.map((t,i)=>`<button class="v14-priority-row" data-v14-task="${esc(t.id)}"><em>${i+1}</em><span><b>${esc(t.title)}</b><small>${esc(t.blockedReason||t.status||'READY')} ${age(t.createdAt)?'• '+age(t.createdAt):''}</small></span><i class="${t.priority==='URGENT'?'hot':''}">${esc(t.priority||'NORMAL')}</i></button>`).join(''):'<div class="v14-empty">ما عندك مهام معلقة. أنشئ مهمة جديدة أو أعطِ أمرًا لأحد الموظفين.</div>'}</div></article>
 <article class="v14-card"><header><div><span>PROJECTS</span><h3>حالة المشاريع</h3></div><button data-v14-go="projects">إدارة المشاريع</button></header><div class="v14-project-health">${(s.projects||[]).map(p=>{const h=projectHealth(p,s);return `<button data-v14-project="${esc(p.id)}"><div><b>${esc(p.name)}</b><small>${esc(p.status||'')} • ${h.total} مهام • ${h.bad} تحتاج انتباه</small></div><div class="v14-meter"><span style="width:${h.score}%"></span></div><strong>${h.score}%</strong></button>`}).join('')||'<div class="v14-empty">ما فيه مشاريع.</div>'}</div></article>
 <article class="v14-card"><header><div><span>TEAM</span><h3>الفريق</h3></div><button data-v14-go="workforce">كل الموظفين</button></header><div class="v14-team-load">${(s.employees||[]).map(e=>{const l=employeeLoad(e,s);const currentTitle=l.current?.title||e.task||'بدون مهمة حالية';return `<button data-v14-employee="${esc(e.id)}"><span class="v14-mini-avatar">${esc((e.name||'AI').slice(0,1))}</span><div><b>${esc(e.name)} <small>• ${esc(statusLabel(e.status))}</small></b><small>${esc(e.role||e.department||'موظف AI')} • ${l.count} مهام مفتوحة</small><small class="v14-current-task">${esc(currentTitle)}</small><div class="v14-load"><span style="width:${l.load}%"></span></div></div><strong>${l.load<35?'متاح':l.load<70?'مشغول':'ضغط عالٍ'}</strong></button>`}).join('')}</div></article>
 <article class="v14-card"><header><div><span>CONNECTED TOOLS</span><h3>الأدوات المربوطة</h3></div><span>تشغيل حقيقي</span></header><div class="v14-tools">
 ${tool('Supabase',systemCloud.cloud===false?'تحقق':'متصل','https://supabase.com/dashboard/project/mydfraaolksbgvoapzrl','الحالة بين الأجهزة')}
 ${tool('GitHub','متصل','https://github.com/uauz1/NAWAFHQ','الكود والتغييرات')}
 ${tool('Render','Live','https://dashboard.render.com','تشغيل NAWAF HQ')}
 ${tool('Slack','تنبيهات','https://newworkspace-iyj2802.slack.com/archives/C0C1YD6M1K7','#nawaf-hq')}
 ${tool('Linear','مزامنة','https://linear.app','المهام والمتابعة')}
 ${tool('Notion','معرفة','https://app.notion.com/p/3dc003d652a28154b179c8273a14c60c','التقارير والقرارات')}
 </div></article>
 <article class="v14-card"><header><div><span>ACTIVITY</span><h3>آخر النشاط</h3></div><button data-v14-action="activity">فتح السجل</button></header><div class="v14-activity">${activity.length?activity.map(a=>`<div><span></span><p><b>${esc(a.text||'نشاط')}</b><small>${age(a.at)}</small></p></div>`).join(''):'<div class="v14-empty">ما فيه نشاط جديد.</div>'}</div></article>
 <article class="v14-card"><header><div><span>QUICK ACTIONS</span><h3>تنفيذ سريع</h3></div></header><div class="v14-quickbar">${quickAction('أمر سريع','quick','gold')}${quickAction('مهمة جديدة','new-task')}${quickAction('المحلل المالي','finance')}${quickAction('قراراتي','decisions')}${quickAction('تطبيقاتي','apps')}</div></article>
</div>`;bind(root)}
function bind(root){root.querySelectorAll('[data-v14-go]').forEach(b=>b.onclick=()=>document.querySelector(`[data-view="${b.dataset.v14Go}"]`)?.click());root.querySelectorAll('[data-v14-task]').forEach(b=>b.onclick=()=>document.querySelector(`[data-task="${CSS.escape(b.dataset.v14Task)}"]`)?.click());root.querySelectorAll('[data-v14-project]').forEach(b=>b.onclick=()=>document.querySelector(`[data-project="${CSS.escape(b.dataset.v14Project)}"]`)?.click());root.querySelectorAll('[data-v14-employee]').forEach(b=>b.onclick=()=>document.querySelector(`[data-employee="${CSS.escape(b.dataset.v14Employee)}"]`)?.click());root.querySelectorAll('[data-v14-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.v14Action;if(a==='quick')document.querySelector('[data-v9-quick]')?.click();else if(a==='new-task')document.querySelector('[data-action="new-task"]')?.click();else if(a==='finance')window.NawafFinance?.open?.();else if(a==='decisions')window.NawafHQV13?.openCenter?.();else if(a==='activity')window.NawafHQV12?.openActivity?.();else if(a==='apps')location.href='apps.html';else if(a==='sync'){b.disabled=true;try{await window.HQCloud?.pull?.();render()}finally{setTimeout(()=>b.disabled=false,600)}}})}
let timer;function schedule(){clearTimeout(timer);timer=setTimeout(render,120)}const obs=new MutationObserver(schedule);function boot(){obs.observe(document.body,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',schedule);setInterval(()=>{if(!document.hidden)render()},15000);render()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();window.NawafHQV14={render};
})();